"""Self-contained, printable inspection report. All target text is escaped."""
import base64
import html
import json
from pathlib import Path
from .presentation import present_finding, present_warning, report_summary, format_date

STATE={'completed':'Tamamlandı','incomplete':'Eksik analiz','failed':'Tamamlanamadı','cancelled':'İptal edildi','rules_only':'Kaynak incelemesi','ai_review':'AI destekli inceleme','dynamic':'İzole davranış testi','not_measured':'Ölçülmedi','undeclared':'Beyan bulunamadı','potential_mismatch':'Kodda uyumsuzluk şüphesi','unresolved':'Çözümlenemedi','no_static_mismatch_observed':'İncelenen kodda uyumsuzluk görülmedi','observed_violation':'Testte ihlal gözlendi','runtime_violation':'Testte ihlal gözlendi','blocked_by_environment':'Test ortamı tarafından engellendi','not_available':'Bu kapsamda incelenmedi'}
SEVERITY={'Critical':'Kritik','High':'Yüksek','Medium':'Orta','Low':'Düşük','Informational':'Bilgi'}
def esc(value):return html.escape(str(value if value is not None else 'Ölçülmedi'))
def text(value):
    if value is None:return 'Ölçülmedi'
    if isinstance(value,list):return '; '.join(text(v) for v in value) if value else 'Kayıt yok'
    if isinstance(value,dict):return text(value.get('target') or value.get('scope') or value.get('message') or value.get('status') or json.dumps(value,ensure_ascii=False))
    return STATE.get(str(value),str(value))

def render_report(scan,base):
    from .risk_score import calculate_risk
    risk=calculate_risk(scan)
    summary=report_summary(scan)
    findings=scan.get('findings',[])
    show_numeric=risk.get('show_numeric',not (summary['remote'] and risk['value']==0))
    risk_number='Uyarı bulunmadı' if not show_numeric and risk['value']==0 else 'Hesaplanamadı' if risk['value'] is None else str(risk['value'])+' / 100'
    score_title=risk.get('metric_label') or ('Araç tanımı öncelik puanı' if summary['remote'] else 'Risk öncelik puanı')
    score_label=('Araç tanımlarında puan ekleyen uyarı bulunmadı' if risk['value']==0 else risk['label']) if summary['remote'] else risk['label']
    factor_rows=[]
    for factor in risk.get('factors',[]):
        original=next((f for f in findings if f.get('finding_id')==factor.get('finding_id')),None)
        target=next((index for index,f in enumerate(findings,1) if f is original),None)
        label=present_finding(original or {'rule_id':factor.get('rule_id')})['title']
        source=(original or {}).get('location') or {};path=source.get('path','');region=source.get('range') or {};line=region.get('start_line')
        source_label=path+(' · '+str(line)+'. satır' if type(line) is int and line>0 else '') if path else 'Kaynak konumu belirtilmedi'
        if factor.get('source_refs'):
            references=[]
            for ref in factor['source_refs']:
                ref_path=ref.get('path') or 'Konum belirtilmedi';ref_line=ref.get('start_line');ref_end=ref.get('end_line')
                region=(' · '+str(ref_line)+(('–'+str(ref_end)) if type(ref_end) is int and ref_end>ref_line else '')+'. satır') if type(ref_line) is int and ref_line>0 else ''
                references.append(ref_path+region)
            source_label='; '.join(references)
        contribution=factor.get('score_contribution')
        contribution_label={'strongest_finding':'Temel ağırlık','additional_finding':'Ek bulgu','bonus_cap':'Ek katkı sınırına ulaşıldı','no_addition':'Puana eklenmez','unscored':'Hesaplanamadı'}.get(factor.get('contribution_kind'),'Ayrıntı kaydedilmedi')
        contribution_text=('—' if contribution is None else str(contribution))+' · '+contribution_label
        basis={'runtime_proven':'İzole testte kaydedilmiş ihlal','static':'Kod incelemesi','contract':'Araç tanımı','unverified_dynamic':'Test kaydı; doğrulanmış ihlal değil','unknown':'Kanıt türü kesinleşmedi'}.get(factor.get('evidence_basis'),'Kanıt türü kesinleşmedi')
        title='<a href="#finding-'+str(target)+'">'+esc(label)+'</a>' if target else esc(label)
        factor_rows.append('<tr><td>'+title+'<br><small>'+esc(source_label)+'</small></td><td>'+esc(SEVERITY.get(factor.get('severity'),'Belirtilmedi'))+'</td><td>'+esc(factor.get('weight'))+'</td><td>'+esc(contribution_text)+'</td><td>'+esc(basis)+'</td></tr>')
    score_calculation=('<p>En yüksek önem ağırlığı: '+esc(risk['strongest_weight'])+' · Ek bulgu katkısı: '+esc(risk['additional_findings_bonus'])+'</p>') if show_numeric else '<p>Kaynak kodu ve çalışma davranışı incelenmedi. Tanımlarda uyarı bulunmaması, sunucunun genel güvenliğini göstermez.</p>'
    risk_markup='<section><h2>'+esc(score_title)+': '+esc(risk_number)+'</h2><p>'+esc(score_label)+'. Bu puan bir olasılık yüzdesi veya güvenlik onayı değildir.</p><p>'+esc(risk['reason'] or risk['formula'])+'</p>'+score_calculation+('<p>Temel ağırlık, en yüksek önem derecesinden gelir. Diğer bulguların katkısı sınırlıdır; tabloda ağırlık ile puana gerçekten eklenen değer ayrı gösterilir.</p><table><thead><tr><th>Puanın dayandığı kayıt / kaynak</th><th>Önem</th><th>Ağırlık</th><th>Puana katkı</th><th>Dayanak</th></tr></thead><tbody>'+''.join(factor_rows)+'</tbody></table>' if factor_rows else '<p>Bu kapsamda puana katkı sağlayan kayıt listelenmedi. İncelemenin tamamlanma durumunu ayrıca kontrol edin.</p>')+'<p>Politika: '+esc(risk['policy_version'])+' · Kapsam: '+esc(summary['scope'])+'</p></section>'
    outcome=summary['title'];action=summary['action']
    logo=Path(base)/'frontend'/'public'/'toollens-logo.png'
    logo_uri='data:image/png;base64,'+base64.b64encode(logo.read_bytes()).decode() if logo.exists() else ''
    sources=scan.get('source_snapshot',{}).get('files',{})
    cards=[]
    for index,f in enumerate(findings,1):
        location=f.get('location') or {};path=location.get('path','');region=location.get('range') or {};line=region.get('start_line');snippet=''
        label=present_finding(f)
        if path in sources and type(line) is int and 0<line<=len(sources[path].splitlines()):
            start=max(1,line-2);lines=sources[path].splitlines()[start-1:line+4]
            snippet='<pre>'+esc('\n'.join(f'{start+i:>4}  {v}' for i,v in enumerate(lines)))+'</pre>'
        source_label=(path or 'Belirtilmedi')+(' · '+str(line)+'. satır' if type(line) is int and line>0 else '')
        raw='<details class="original-record"><summary>Özgün teknik açıklama</summary><p><b>Başlık:</b> '+esc(f.get('title','Belirtilmedi'))+'</p><p>'+esc(f.get('description','Belirtilmedi'))+'</p><p><b>Özgün öneri:</b> '+esc(f.get('remediation','Belirtilmedi'))+'</p></details>'
        cards.append(f'<article class="finding" id="finding-{index}"><div class="finding-head"><span class="severity">{esc(SEVERITY.get(f.get("severity"),"İnceleme"))}</span><span>{esc(f.get("rule_id",""))} · {index:02}</span></div><h3>{esc(label["title"])}</h3><p>{esc(label["why"])}</p><div class="recommendation"><b>Önerilen adım</b><p>{esc(label["fix"])}</p></div><p class="source">Kaynak: {esc(source_label)}</p>{snippet}{raw}</article>')
    permission_rows=[]
    for p in scan.get('permissions',[]):
        operation={'filesystem.read':'Dosya okuma','filesystem.write':'Dosya yazma','network':'Ağ bağlantısı'}.get(p.get('capability'),p.get('capability',''))
        permission_rows.append('<tr>'+''.join('<td>'+esc(text(v))+'</td>' for v in (p.get('tool',''),operation,p.get('declared'),p.get('inferred'),p.get('observed'),p.get('assessment')) )+'</tr>')
    ai=''.join(f'<article class="ai-note"><b>{esc(r.get("provider","AI"))} · {esc(r.get("model",""))}</b><p>{esc(r.get("content") or r.get("error") or "AI yorumu bulunmuyor.")}</p><small>Model değerlendirmesidir; çalışma anında doğrulanmış test sonucu değildir.</small></article>' for r in scan.get('ai_reviews',[]))
    stages=''.join(f'<tr><td>{esc({"preparing":"Hazırlık","static":"Kod incelemesi","inventory":"Araç ve yetki bilgileri","ai":"AI değerlendirmesi","dynamic":"Davranış testi","reporting":"Rapor"}.get(s["name"],s["name"]))}</td><td>{esc({"succeeded":"Tamamlandı","skipped":"Çalıştırılmadı","failed":"Tamamlanamadı","pending":"Çalıştırılmadı","running":"Sürüyor"}.get(s["status"],s["status"]))}</td><td>{esc(s.get("reason") or "—")}</td></tr>' for s in scan.get('stages',[]))
    warning=''.join('<li>'+esc(present_warning(w))+'<details class="original-record"><summary>Özgün teknik kayıt</summary><p>'+esc(text(w))+'</p></details></li>' for w in scan.get('warnings',[]))
    source_count=len(sources);tool_count=len(scan.get('tools',[]))
    return f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ToolLens · {esc(scan.get('project_name','Kontrol raporu'))}</title><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#eceef1;color:#172333;font:14px/1.75 Arial,sans-serif}}.sheet{{max-width:990px;margin:35px auto;background:white;padding:52px 64px;box-shadow:0 12px 50px #18223312}}header{{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d8dfe7;padding-bottom:25px}}.brand{{display:flex;align-items:center;gap:12px;font-size:25px;font-weight:700}}.brand img{{width:40px;height:40px;object-fit:contain}}.caption{{font-size:10px;letter-spacing:1.8px;color:#657386}}.report-title{{margin:35px 0 28px}}h1{{font:400 35px/1.3 Georgia,serif;margin:12px 0}}h2{{font:400 24px/1.35 Georgia,serif;margin:0 0 18px}}h3{{font-size:16px;line-height:1.6;margin:13px 0}}p{{margin:10px 0}}.muted,small{{color:#657386}}.meta{{display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:12px;overflow-wrap:anywhere}}.meta b{{display:block;color:#657386;font-weight:400}}.outcome{{padding:25px;border:1px solid #c9d9ed;border-left:4px solid #3274bf;background:#f3f7fc;border-radius:5px;margin:25px 0}}.outcome h2{{font-family:Arial;font-size:22px;margin:8px 0 12px}}.metrics{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:35px}}.metric{{padding:17px;border:1px solid #dbe2e9;border-radius:5px}}.metric strong{{display:block;font-size:28px;color:#254569}}.metric span{{font-size:11px;color:#657386}}section{{margin:35px 0;break-inside:auto}}.finding{{padding:23px;border:1px solid #dbe2e9;border-radius:6px;margin-bottom:18px;break-inside:avoid}}.finding-head{{display:flex;justify-content:space-between;align-items:center;color:#657386;font-size:11px}}.severity{{color:#754025;background:#faf0e9;padding:3px 10px;border-radius:4px}}.recommendation{{padding:12px 15px;background:#f6f8fa;border-radius:4px;font-size:12px}}.recommendation p{{margin-bottom:0}}.source{{font-size:11px;color:#52657b;overflow-wrap:anywhere}}pre{{font:10px/1.65 monospace;white-space:pre-wrap;overflow-wrap:anywhere;padding:14px;background:#f5f7fa;border:1px solid #e1e6ed;border-radius:4px}}table{{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px;line-height:1.7}}th,td{{padding:10px 8px;border:1px solid #dbe2e9;text-align:left;vertical-align:top;overflow-wrap:anywhere}}th{{background:#eff3f7;color:#3d5069}}tr{{break-inside:avoid}}thead{{display:table-header-group}}.ai-note{{padding:20px;background:#f5f7fa;border-left:2px solid #9aaec7;margin:15px 0;font-size:12px;white-space:pre-wrap;break-inside:avoid}}.ai-note small{{font-size:10px}}details{{margin-top:12px;font-size:11px}}summary{{cursor:pointer;color:#405d7b}}details p{{overflow-wrap:anywhere}}a{{color:#245d98;text-decoration:underline}}.finding{{scroll-margin-top:20px}}footer{{border-top:1px solid #dbe2e9;margin-top:45px;padding-top:20px;font-size:10px;color:#657386;display:flex;justify-content:space-between;gap:20px}}.printbar{{max-width:990px;margin:25px auto;text-align:right}}.printbar button{{padding:12px 20px;background:#152b46;border:0;color:white;border-radius:6px;cursor:pointer}}.limit{{padding:17px;background:#faf9f5;border:1px solid #e9e3d5;border-radius:5px;font-size:12px}}@page{{size:A4;margin:16mm}}@media print{{body{{background:white;font-size:11px}}.sheet{{padding:0;margin:0;box-shadow:none;max-width:none}}.printbar{{display:none}}h1{{font-size:29px}}h2{{font-size:21px}}header,footer,.outcome,.metrics{{break-inside:avoid}}.finding{{padding:16px}}.original-record{{display:none}}}}@media(max-width:700px){{.sheet{{padding:25px;margin:12px}}.meta{{grid-template-columns:1fr}}.metrics{{gap:6px}}.metric{{padding:12px}}h1{{font-size:28px}}}}
    </style></head><body><div class="printbar"><button onclick="window.print()">Yazdır / PDF olarak kaydet</button></div><main class="sheet"><header><div class="brand">{f'<img src="{logo_uri}" alt="ToolLens logosu">' if logo_uri else ''}ToolLens<span style="color:#3274bf">.</span></div><span class="caption">{"ARAÇ TANIMI İNCELEMESİ" if summary['remote'] else "GÜVENLİK VE RİSK İNCELEMESİ"}</span></header><div class="report-title"><span class="caption">KONTROL RAPORU</span><h1>{esc(scan.get('project_name','MCP projesi'))}</h1><p class="muted">{"Kaynak kodu paylaşılmayan MCP sunucusunun yayımladığı araç tanımlarının incelemesi." if summary['remote'] else "Yapay zekâ araçları için kaynak, izin ve güvenlik incelemesi."}</p></div><div class="meta"><div><b>Kontrol zamanı</b>{esc(format_date(scan.get('started_at') or scan.get('created_at')))}</div><div><b>İnceleme yöntemi</b>{esc(('Araç tanımları ve yapay zekâ yorumu' if scan.get('profile')=='ai_review' else 'Araç tanımı incelemesi') if summary['remote'] else STATE.get(scan.get('profile'),scan.get('profile')))}</div><div><b>Kontrol kimliği</b>{esc(scan.get('id'))}</div><div><b>Tamamlanma durumu</b>{esc(STATE.get(scan.get('status'),scan.get('status')))}</div></div><div class="outcome"><span class="caption">SONUÇ VE SONRAKİ ADIM</span><h2>{esc(outcome)}</h2><p>{esc(action)}</p>{'<p>'+esc(scan['error'])+'</p>' if scan.get('error') else ''}</div>{risk_markup}<div class="metrics"><div class="metric"><strong>{len(findings)}</strong><span>İncelenecek bulgu</span></div><div class="metric"><strong>{tool_count}</strong><span>Tanımlanan araç</span></div><div class="metric"><strong>{source_count if sources else '—'}</strong><span>Kayıtlı kaynak dosyası</span></div></div><section><h2>1. İncelemenin kapsamı</h2><p>{'Yalnız HTTP MCP üzerinden yayımlanan araç tanımları alındı. Kaynak kodu incelenmedi; uzak araçlar çağrılmadı.' if scan.get('analysis_kind')=='remote_contract' else 'Kaynak kodu için seçilen desteklenen kontrollerin durumu aşağıda gösterilir. Araç ve yetki bilgileri kaynak görüntüsünden çıkarıldı. Kod çıkarımı, çalışma sırasında gözlenen davranış değildir.'}</p><table><thead><tr><th>Aşama</th><th>Durum</th><th>Açıklama</th></tr></thead><tbody>{stages}</tbody></table></section><section><h2>2. Bulgular ve önerilen adımlar</h2>{''.join(cards) if cards else '<p>Bu kayıtta listelenecek bulgu yok. İncelemenin tamamlanma durumunu ve kapsamını yukarıdan kontrol edin.</p>'}</section>{'<section><h2>3. Araçlar ve erişimler</h2><p>Beyan, kaynak koddan çıkarılan erişim ve test gözlemi ayrı gösterilir. Ölçülmedi ifadesi, işlemin güvenli olduğu anlamına gelmez.</p><table><thead><tr><th>Araç</th><th>İşlem</th><th>Beyan</th><th>Kod çıkarımı</th><th>Test gözlemi</th><th>Değerlendirme</th></tr></thead><tbody>'+''.join(permission_rows)+'</tbody></table></section>' if permission_rows else ''}{'<section><h2>Yapay zekâ değerlendirmesi</h2>'+ai+'</section>' if ai else ''}<section><h2>Sınırlamalar</h2><div class="limit">Bu rapor bir güvenlik sertifikası değildir. İncelenmeyen kod, koşul veya davranış hakkında güvenli sonucu çıkarılamaz. AI yorumları insan incelemesini destekler; test kanıtı yerine geçmez.</div>{'<ul>'+warning+'</ul>' if warning else ''}</section><details><summary>Teknik kayıt ve karar politikası</summary><p>Dörtlü Karar Kutusu · tl-decision-v1. İnsan incelemesi ile test kanıtı ayrı tutulur. Özgün motor JSON ve SARIF kayıtları uygulamadan alınabilir.</p><p>Analiz bileşenlerinin kaynak ve lisans bilgileri ToolLens lisans bildirimlerinde korunur.</p></details><footer><strong>ToolLens · Kontrol raporu</strong><span>Kaynak kimliği: {esc(str(scan.get('source_hash') or 'Kaydedilmedi')[:16])}</span></footer></main></body></html>'''
